import{_ as n,a0 as s,w as d,s as p,ao as l,I as o,x as t,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Fedora 上使用 GIMP 輕鬆編輯圖像 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 上使用 GIMP 輕鬆編輯圖像 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 上使用 GIMP 輕鬆編輯圖像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 上使用 GIMP 輕鬆編輯圖像 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191113 Edit images on Fedora easily with GIMP","title":"在 Fedora 上使用 GIMP 輕鬆編輯圖像","tag":"201912","desc":""},"relativePath":"201912/20191113 Edit images on Fedora easily with GIMP.md","filePath":"[post].md"}'),g={name:"201912/20191113 Edit images on Fedora easily with GIMP.md"};function m(u,a,h,b,f,y){const r=s("Link");return d(),p("div",null,[a[15]||(a[15]=l('<h1 id="在-fedora-上使用-gimp-輕鬆編輯圖像" tabindex="-1">在 Fedora 上使用 GIMP 輕鬆編輯圖像 <a class="header-anchor" href="#在-fedora-上使用-gimp-輕鬆編輯圖像" aria-label="Permalink to “在 Fedora 上使用 GIMP 輕鬆編輯圖像”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/gimp-magazine-816x346.jpg" alt=""></p><p>GIMP（GNU Image Manipulation Program 的縮寫）是自由開源的圖像處理軟件。它有很多的功能，從簡單的圖像編輯，到複雜的濾鏡、腳本，甚至是動畫，它是流行的商業同類軟件的一款很好的替代品。</p><p>繼續閲讀來學習如何在 Fedora 上安裝和使用 GIMP。這篇文章涉及基本的日常圖像編輯工作。</p><h3 id="安裝-gimp" tabindex="-1">安裝 GIMP <a class="header-anchor" href="#安裝-gimp" aria-label="Permalink to “安裝 GIMP”">​</a></h3><p>GIMP 在官方 Fedora 存儲庫中可獲得。為安裝它，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install gimp</span></span></code></pre></div><h3 id="單窗口模式" tabindex="-1">單窗口模式 <a class="header-anchor" href="#單窗口模式" aria-label="Permalink to “單窗口模式”">​</a></h3><p>在你打開應用程序後，它顯示帶有工具箱和主編輯區的暗色主題窗口。注意，它有兩種窗口模式，你可以通過選擇“<ruby>窗口<rt>Windows</rt></ruby> -&gt; <ruby>單窗口模式<rt>Single Window Mode</rt></ruby>”在其中切換。通過選中這個選項，用户界面的所有組件將顯示在單個窗口中。否則，它們將是分離的。</p><h3 id="加載圖像" tabindex="-1">加載圖像 <a class="header-anchor" href="#加載圖像" aria-label="Permalink to “加載圖像”">​</a></h3><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-00-44-300x165.png" alt=""></p><p>為加載圖像，轉到“<ruby>文件<rt>File</rt></ruby> -&gt; <ruby>打開<rt>Open</rt></ruby>”，然後選擇你的文件並選擇你的圖像文件。</p><h3 id="重新調整一個圖像的大小" tabindex="-1">重新調整一個圖像的大小 <a class="header-anchor" href="#重新調整一個圖像的大小" aria-label="Permalink to “重新調整一個圖像的大小”">​</a></h3><p>為重新調整圖像大小，你可以基於一對參數重新調整大小，包括像素和百分比 —— 在編輯圖像時，這兩個參數很方便。</p><p>讓我們假使我們需要縮小 Fedora 30 背景圖像到它當前大小的 75%。為此，選擇“<ruby>圖像<rt> Image</rt></ruby> -&gt; <ruby>比例<rt>Scale</rt></ruby>”，然後在比例對話框上，在單位下拉列表中選擇“<ruby>百分比<rt>percentage</rt></ruby>”。接下來，輸入 “75” 作為寬度或高度，然後按 Tab 鍵。默認情況下，其它尺寸將自動地調整大小，以相應地與更改的尺寸保持縱橫比。現在，保存其它選項不變，並按比例。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-17-33-300x262.png" alt=""></p><p>該圖像縮小到其原始尺寸的 75%。</p><h3 id="旋轉圖像" tabindex="-1">旋轉圖像 <a class="header-anchor" href="#旋轉圖像" aria-label="Permalink to “旋轉圖像”">​</a></h3><p>旋轉是一種變換操作，因此，你可以從主菜單下的“<ruby>圖像<rt>Image</rt></ruby> -&gt; <ruby>變換<rt>Transform</rt></ruby>”下找到它，其中有圖像旋轉 90° 或 180° 的選項。在上述選項下也有垂直或水平翻轉圖像的選項。</p><p>讓我們假使我們需要旋轉圖像 90°。在應用一次 90° 順時針旋轉和水平翻轉後，我們的圖像將看起來像這樣：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-41-28-300x243.png" alt="Transforming an image with GIMP"></p><h3 id="添加文本" tabindex="-1">添加文本 <a class="header-anchor" href="#添加文本" aria-label="Permalink to “添加文本”">​</a></h3><p>添加文本非常簡單。只需要從工具箱中選擇 “A” 圖標，然後，在你的圖像上，單擊你想要添加文本的位置。如果工具箱不可見，從“<ruby>窗口<rt>Windows</rt></ruby> -&gt; <ruby>新建工具箱<rt>New Toolbox</rt></ruby>”打開它。</p><p>當你編輯文本時，你可能注意到，文本對話框有字體自定義選項，包括字體系列、字體大小等等。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/Screenshot-from-2019-10-25-11-47-54-300x237.png" alt="Adding text to image in GIMP"></p><h3 id="保存和導出" tabindex="-1">保存和導出 <a class="header-anchor" href="#保存和導出" aria-label="Permalink to “保存和導出”">​</a></h3><p>你可以從“<ruby>文件<rt>File</rt></ruby> -&gt; <ruby>保存<rt>Save</rt></ruby>”或通過按 <code>Ctrl+S</code> 來將你的編輯保存為一個帶有 <code>.xcf</code> 擴展名的 GIMP 工程。或者，你可以導出你的圖像，例如，以 PNG 或 JPEG 格式。為導出圖像，轉到“<ruby>文件<rt>File</rt></ruby> -&gt; <ruby>導出為<rt>Export As</rt></ruby>”或按 <code>Ctrl+Shift+E</code>，接下來，在你面前將產生一個你可以選擇輸出圖像和名稱的對話框。</p><hr>',28)),o("p",null,[a[1]||(a[1]=t("via: ",-1)),e(r,{href:"https://fedoramagazine.org/edit-images-on-fedora-easily-with-gimp/"},{default:i(()=>[...a[0]||(a[0]=[t("https://fedoramagazine.org/edit-images-on-fedora-easily-with-gimp/",-1)])]),_:1})]),o("p",null,[a[6]||(a[6]=t("作者：",-1)),e(r,{href:"https://fedoramagazine.org/author/powergame/"},{default:i(()=>[...a[2]||(a[2]=[t("Mehdi Haghgoo",-1)])]),_:1}),a[7]||(a[7]=t(" 選題：",-1)),e(r,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[t("lujun9972",-1)])]),_:1}),a[8]||(a[8]=t(" 譯者：",-1)),e(r,{href:"https://github.com/robsean"},{default:i(()=>[...a[4]||(a[4]=[t("robsean",-1)])]),_:1}),a[9]||(a[9]=t(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[a[12]||(a[12]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[t("LCTT",-1)])]),_:1}),a[13]||(a[13]=t(" 原創編譯，",-1)),e(r,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[t("Linux中國",-1)])]),_:1}),a[14]||(a[14]=t(" 榮譽推出",-1))])])}const M=n(g,[["render",m]]);export{T as __pageData,M as default};
